/// Name of the `Module._extensions` handler compiling a file (shows up in stack traces).
fn handler_name(ext: &str) -> &'static str {
    match ext {
        "ts" => ".ts",
        "cts" => ".cts",
        "json" => ".json",
        _ => ".js",
