const React = {
  createElement(type, props, ...children) {
    return { type, props: props || {}, children };
  },
  Fragment: Symbol("Fragment"),
};
function render(node) {
  if (node == null || node === false || node === true) return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(render).join("");
  if (typeof node.type === "function") return render(node.type({ ...node.props, children: node.children }));
  if (node.type === React.Fragment) return node.children.map(render).join("");
  const attrs = Object.entries(node.props).map(([k, v]) => ` ${k === "className" ? "class" : k}="${v}"`).join("");
  return `<${node.type}${attrs}>${node.children.map(render).join("")}</${node.type}>`;
}
const Greeting = ({ name }) => <h1 className="title">Hello, {name}!</h1>;
const App = () => (
  <div id="app">
    <Greeting name="World" />
    <ul>
      {["a", "b", "c"].map((x) => (
        <li key={x}>{x.toUpperCase()}</li>
      ))}
    </ul>
    <>
      <span>frag</span>
    </>
    {false && <p>hidden</p>}
    {0}
  </div>
);
console.log(render(<App />));
