const fs = require('fs'), path = require('path');
const acorn = require('/usr/share/nodejs/acorn');
const walk = (dir, files) => { for (const e of fs.readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) { walk(p, files); } else if (p.endsWith('.js') && !p.includes('.min.')) files.push(p); } return files; };
const files = walk('/usr/share/nodejs', []);
const regexes = new Map(); const strings = new Set();
for (const f of files) {
  let src; try { src = fs.readFileSync(f, 'utf8'); } catch (e) { continue; }
  if (src.length > 400000) continue;
  let ast;
  try { ast = acorn.parse(src, { ecmaVersion: 'latest', sourceType: 'module', allowHashBang: true, allowReturnOutsideFunction: true }); } catch (e) { try { ast = acorn.parse(src, { ecmaVersion: 'latest', sourceType: 'script', allowHashBang: true, allowReturnOutsideFunction: true }); } catch (e2) { continue; } }
  const stack = [ast];
  while (stack.length) {
    const n = stack.pop();
    if (!n || typeof n.type !== 'string') continue;
    if (n.type === 'Literal') {
      if (n.regex) { const k = JSON.stringify([n.regex.pattern, n.regex.flags]); regexes.set(k, (regexes.get(k) || 0) + 1); }
      else if (typeof n.value === 'string' && n.value.length > 0 && n.value.length < 80 && strings.size < 20000) strings.add(n.value);
