        env: RefCell::new(None),
        env_names: Vec::new(),
        frame: RefCell::new(None),
        code: None,
        imports: Vec::new(),
        import_bindings: RefCell::new(Vec::new()),
        local_exports: Vec::new(),
        indirect_exports: Vec::new(),
        star_exports: Vec::new(),
        requested: Vec::new(),
